import { ok, fail } from './result.js';
import { getCustomer, TIER_DISCOUNTS, normalizeId } from './customers.js';
import { getProduct } from './catalogue.js';
import { nextInvoiceNumber } from './numbering.js';
import { isValidDate, addDays } from './dates.js';
import { lineTotal, lineDiscount, lineVAT, invoiceTotals } from './totals.js';

// Re-export totals functions for backward compatibility
export { lineTotal, lineDiscount, lineVAT, invoiceTotals };

/**
 * Create a new invoice.
 * @param {{ customerId: string, issueDate: string, lines: Array<{ sku: string, qty: number }>, terms?: string }} input
 * @returns {{ ok: true, value: { customerId: string, issueDate: string, status: 'draft', lines: Array, terms: string, dueDate: string } } | { ok: false, error: string }}
 */
export function createInvoice({ customerId, issueDate, lines, terms = 'NET30' }) {
  // Normalize customer ID
  const normalizedCustomerId = normalizeId(customerId);

  // Validate customer
  const customerResult = getCustomer(normalizedCustomerId);
  if (!customerResult.ok) return customerResult;
  const customer = customerResult.value;

  // Validate issue date
  if (!isValidDate(issueDate)) {
    return fail('DATE_INVALID');
  }

  // Validate and calculate due date based on terms
  const termsError = validateTerms(terms);
  if (termsError) return fail(termsError);
  const dueDate = calculateDueDate(issueDate, terms);

  // Validate lines array
  if (!Array.isArray(lines) || lines.length === 0) {
    return fail('NO_LINES');
  }

  // Process and validate each line
  const processedLines = [];
  for (const line of lines) {
    // Validate quantity
    if (!Number.isInteger(line.qty) || line.qty <= 0) {
      return fail('QTY_INVALID');
    }

    // Determine discount: explicit value wins, otherwise use tier discount
    const discountPercent = line.discountPercent !== undefined && line.discountPercent !== null
      ? line.discountPercent
      : TIER_DISCOUNTS[customer.tier];

    // Validate discount percent
    const discountError = validateDiscountPercent(discountPercent);
    if (discountError) return fail(discountError);

    // Validate SKU and get product
    const productResult = getProduct(line.sku);
    if (!productResult.ok) return productResult;

    const product = productResult.value;
    processedLines.push({
      sku: line.sku,
      name: product.name,
      qty: line.qty,
      unitPrice: product.unitPrice,
      vatRate: product.vatRate,
      discountPercent,
    });
  }

  // Build invoice
  const invoice = {
    customerId: normalizedCustomerId,
    issueDate,
    status: 'draft',
    terms,
    dueDate,
    lines: processedLines,
  };

  return ok(invoice);
}

/**
 * Add or increase a line on a draft invoice.
 * @param {{ status: string, customerId: string, lines: Array<{ sku: string, qty: number }> }} invoice
 * @param {{ sku: string, qty: number, discountPercent?: number }} input
 * @returns {{ ok: true, value: object } | { ok: false, error: string }}
 */
export function addLine(invoice, { sku, qty, discountPercent }) {
  // Check status
  if (invoice.status !== 'draft') {
    return fail('NOT_DRAFT');
  }

  // Validate quantity
  if (!Number.isInteger(qty) || qty <= 0) {
    return fail('QTY_INVALID');
  }

  // Get customer for tier discount
  const customerResult = getCustomer(invoice.customerId);
  if (!customerResult.ok) return customerResult;
  const customer = customerResult.value;

  // Determine discount: explicit value wins, otherwise use tier discount
  const finalDiscount = discountPercent !== undefined && discountPercent !== null
    ? discountPercent
    : TIER_DISCOUNTS[customer.tier];

  // Validate discount percent
  const discountError = validateDiscountPercent(finalDiscount);
  if (discountError) return fail(discountError);

  // Validate SKU and get product
  const productResult = getProduct(sku);
  if (!productResult.ok) return productResult;

  // Create new invoice with updated lines
  const newLines = invoice.lines.map((line) => ({ ...line }));
  const existingLineIndex = newLines.findIndex((line) => line.sku === sku);

  if (existingLineIndex >= 0) {
    // Line exists, increase qty
    newLines[existingLineIndex] = {
      ...newLines[existingLineIndex],
      qty: newLines[existingLineIndex].qty + qty,
    };
  } else {
    // New line, add it
    const product = productResult.value;
    newLines.push({
      sku,
      name: product.name,
      qty,
      unitPrice: product.unitPrice,
      vatRate: product.vatRate,
      discountPercent: finalDiscount,
    });
  }

  // Return new invoice
  const newInvoice = {
    ...invoice,
    lines: newLines,
  };
  return ok(newInvoice);
}

/**
 * Remove a line from a draft invoice.
 * @param {{ status: string, lines: Array<{ sku: string }> }} invoice
 * @param {string} sku
 * @returns {{ ok: true, value: object } | { ok: false, error: string }}
 */
export function removeLine(invoice, sku) {
  // Check status
  if (invoice.status !== 'draft') {
    return fail('NOT_DRAFT');
  }

  // Find the line
  const lineIndex = invoice.lines.findIndex((line) => line.sku === sku);
  if (lineIndex < 0) {
    return fail('LINE_NOT_FOUND');
  }

  // Check if this is the last line
  if (invoice.lines.length === 1) {
    return fail('NO_LINES');
  }

  // Create new invoice without this line
  const newLines = invoice.lines.filter((line) => line.sku !== sku);
  const newInvoice = {
    ...invoice,
    lines: newLines,
  };
  return ok(newInvoice);
}

/**
 * Apply a voucher to a draft invoice.
 * @param {{ status: string, voucher?: object }} invoice
 * @param {{ code: string, amount: number }} input - amount in cents
 * @returns {{ ok: true, value: object } | { ok: false, error: string }}
 */
export function applyVoucher(invoice, { code, amount }) {
  // Check status - must be draft
  if (invoice.status !== 'draft') {
    return fail('NOT_DRAFT');
  }

  // Check if voucher already exists
  if (invoice.voucher) {
    return fail('VOUCHER_EXISTS');
  }

  // Validate amount
  if (!Number.isInteger(amount) || amount <= 0) {
    return fail('AMOUNT_INVALID');
  }

  // Create new invoice with voucher
  const newInvoice = {
    ...invoice,
    voucher: { code, amount },
  };

  return ok(newInvoice);
}

/**
 * Issue a draft invoice.
 * @param {{ status: string, issueDate: string }} invoice
 * @param {Array<string>} existingNumbers array of invoice numbers already used
 * @returns {{ ok: true, value: object } | { ok: false, error: string }}
 */
export function issueInvoice(invoice, existingNumbers) {
  // Check status
  if (invoice.status !== 'draft') {
    return fail('NOT_DRAFT');
  }

  // Generate invoice number
  const number = nextInvoiceNumber(existingNumbers, invoice.issueDate);

  // Return new invoice with number and issued status
  const newInvoice = {
    ...invoice,
    number,
    status: 'issued',
  };
  return ok(newInvoice);
}

/**
 * Validate payment terms.
 * @param {string} termsStr
 * @returns {string | null} error code or null if valid
 */
function validateTerms(termsStr) {
  if (!['NET14', 'NET30', 'EOM'].includes(termsStr)) {
    return 'TERMS_INVALID';
  }
  return null;
}

/**
 * Calculate due date based on invoice date and payment terms.
 * @param {string} issueDate - date in YYYY-MM-DD format
 * @param {string} terms - 'NET14', 'NET30', or 'EOM'
 * @returns {string} due date in YYYY-MM-DD format
 */
function calculateDueDate(issueDate, terms) {
  if (terms === 'NET14') {
    return addDays(issueDate, 14);
  } else if (terms === 'NET30') {
    return addDays(issueDate, 30);
  } else if (terms === 'EOM') {
    return getLastDayOfMonth(issueDate);
  }
}

/**
 * Get the last day of the month for a given date.
 * @param {string} dateStr - date in YYYY-MM-DD format
 * @returns {string} last day of month in YYYY-MM-DD format
 */
function getLastDayOfMonth(dateStr) {
  const date = new Date(`${dateStr}T00:00:00Z`);
  const year = date.getUTCFullYear();
  const month = date.getUTCMonth();

  // Get first day of next month, then subtract 1 day
  const nextMonthFirstDay = new Date(Date.UTC(year, month + 1, 1));
  const lastDayOfMonth = new Date(nextMonthFirstDay.getTime() - 24 * 60 * 60 * 1000);

  // Format as YYYY-MM-DD
  const resultYear = lastDayOfMonth.getUTCFullYear();
  const resultMonth = String(lastDayOfMonth.getUTCMonth() + 1).padStart(2, '0');
  const resultDay = String(lastDayOfMonth.getUTCDate()).padStart(2, '0');
  return `${resultYear}-${resultMonth}-${resultDay}`;
}

/**
 * Validate discount percent value.
 * @param {unknown} value
 * @returns {string | null} error code or null if valid
 */
function validateDiscountPercent(value) {
  if (value === undefined || value === null) {
    return null;
  }
  if (typeof value !== 'number' || value < 0 || value > 100) {
    return 'DISCOUNT_INVALID';
  }
  return null;
}

