test('invoiceTotals with discount and VAT', () => {
  const invoice = {
    customerId: 'C-002',
    issueDate: '2026-10-07',
    status: 'draft',
    lines: [{ qty: 10, unitPrice: 10000, discountPercent: 20, vatRate: 21 }],
  };
  const totals = invoiceTotals(invoice);
