import test from 'node:test';
import assert from 'node:assert/strict';
import { createInvoice, lineTotal, invoiceTotals, addLine, removeLine, issueInvoice, lineDiscount, lineVAT, applyVoucher } from '../src/invoices.js';

test('createInvoice creates a draft invoice with product details', () => {
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  });
  assert.equal(result.ok, true);
  const inv = result.value;
  assert.equal(inv.customerId, 'C-001');
  assert.equal(inv.issueDate, '2026-10-07');
  assert.equal(inv.status, 'draft');
  assert.equal(inv.lines.length, 1);
  assert.equal(inv.lines[0].sku, 'DES-HOUR');
  assert.equal(inv.lines[0].name, 'Design work (hour)');
  assert.equal(inv.lines[0].qty, 5);
  assert.equal(inv.lines[0].unitPrice, 8500);
  assert.equal(inv.lines[0].vatRate, 21);
});

test('createInvoice normalizes customer ID', () => {
  const result = createInvoice({
    customerId: '  c-001  ',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  });
  assert.equal(result.ok, true);
  assert.equal(result.value.customerId, 'C-001');
});

test('createInvoice accepts lowercase customer ID', () => {
  const result = createInvoice({
    customerId: 'c-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  });
  assert.equal(result.ok, true);
  assert.equal(result.value.customerId, 'C-001');
});

test('createInvoice defaults to NET30 terms', () => {
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  });
  assert.equal(result.ok, true);
  assert.equal(result.value.terms, 'NET30');
  assert.equal(result.value.dueDate, '2026-11-06');
});

test('createInvoice accepts NET14 terms', () => {
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
    terms: 'NET14',
  });
  assert.equal(result.ok, true);
  assert.equal(result.value.terms, 'NET14');
  assert.equal(result.value.dueDate, '2026-10-21');
});

test('createInvoice accepts NET30 terms', () => {
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
    terms: 'NET30',
  });
  assert.equal(result.ok, true);
  assert.equal(result.value.terms, 'NET30');
  assert.equal(result.value.dueDate, '2026-11-06');
});

test('createInvoice accepts EOM terms', () => {
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
    terms: 'EOM',
  });
  assert.equal(result.ok, true);
  assert.equal(result.value.terms, 'EOM');
  assert.equal(result.value.dueDate, '2026-10-31');
});

test('createInvoice rejects invalid terms', () => {
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
    terms: 'NET45',
  });
  assert.equal(result.ok, false);
  assert.equal(result.error, 'TERMS_INVALID');
});

test('createInvoice EOM handles month boundaries', () => {
  // February 2024 (leap year) has 29 days
  const result1 = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-02-15',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
    terms: 'EOM',
  });
  assert.equal(result1.value.dueDate, '2024-02-29');

  // February 2025 (not leap year) has 28 days
  const result2 = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-02-15',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
    terms: 'EOM',
  });
  assert.equal(result2.value.dueDate, '2025-02-28');

  // December has 31 days
  const result3 = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-12-01',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
    terms: 'EOM',
  });
  assert.equal(result3.value.dueDate, '2026-12-31');
});

test('createInvoice NET14 with month boundary', () => {
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-25',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
    terms: 'NET14',
  });
  assert.equal(result.value.dueDate, '2026-11-08');
});

test('createInvoice NET30 with year boundary', () => {
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-12-15',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
    terms: 'NET30',
  });
  assert.equal(result.value.dueDate, '2027-01-14');
});

test('applyVoucher adds voucher to draft invoice', () => {
  const result = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  });
  const invoice = result.value;

  const voucherResult = applyVoucher(invoice, { code: 'SUMMER10', amount: 5000 });
  assert.equal(voucherResult.ok, true);
  assert.equal(voucherResult.value.voucher.code, 'SUMMER10');
  assert.equal(voucherResult.value.voucher.amount, 5000);
});

test('applyVoucher rejects voucher on non-draft invoice', () => {
  const result = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  });
  const invoice = issueInvoice(result.value, []).value;

  const voucherResult = applyVoucher(invoice, { code: 'SUMMER10', amount: 5000 });
  assert.equal(voucherResult.ok, false);
  assert.equal(voucherResult.error, 'NOT_DRAFT');
});

test('applyVoucher rejects second voucher', () => {
  const result = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  });
  let invoice = result.value;

  // Apply first voucher
  const voucher1 = applyVoucher(invoice, { code: 'SUMMER10', amount: 5000 });
  assert.equal(voucher1.ok, true);
  invoice = voucher1.value;

  // Try to apply second voucher
  const voucher2 = applyVoucher(invoice, { code: 'WINTER20', amount: 10000 });
  assert.equal(voucher2.ok, false);
  assert.equal(voucher2.error, 'VOUCHER_EXISTS');
});

test('applyVoucher rejects zero amount', () => {
  const result = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  });
  const invoice = result.value;

  const voucherResult = applyVoucher(invoice, { code: 'INVALID', amount: 0 });
  assert.equal(voucherResult.ok, false);
  assert.equal(voucherResult.error, 'AMOUNT_INVALID');
});

test('applyVoucher rejects negative amount', () => {
  const result = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  });
  const invoice = result.value;

  const voucherResult = applyVoucher(invoice, { code: 'INVALID', amount: -1000 });
  assert.equal(voucherResult.ok, false);
  assert.equal(voucherResult.error, 'AMOUNT_INVALID');
});

test('applyVoucher rejects fractional amount', () => {
  const result = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  });
  const invoice = result.value;

  const voucherResult = applyVoucher(invoice, { code: 'INVALID', amount: 5000.5 });
  assert.equal(voucherResult.ok, false);
  assert.equal(voucherResult.error, 'AMOUNT_INVALID');
});

test('invoiceTotals includes voucher in calculation', () => {
  const result = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  });
  let invoice = result.value;
  const totals1 = invoiceTotals(invoice);

  // Apply voucher
  const voucherResult = applyVoucher(invoice, { code: 'SUMMER10', amount: 5000 });
  invoice = voucherResult.value;
  const totals2 = invoiceTotals(invoice);

  assert.equal(totals2.voucher, 5000);
  assert.equal(totals2.total, totals1.total - 5000);
});

test('invoiceTotals voucher defaults to 0', () => {
  const result = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  });

  const totals = invoiceTotals(result.value);
  assert.equal(totals.voucher, 0);
});

test('invoiceTotals voucher clamps total at 0', () => {
  const result = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  });
  let invoice = result.value;
  const totals1 = invoiceTotals(invoice);

  // Apply voucher larger than total
  const voucherResult = applyVoucher(invoice, { code: 'HUGE', amount: totals1.total + 10000 });
  invoice = voucherResult.value;
  const totals2 = invoiceTotals(invoice);

  assert.equal(totals2.voucher, totals1.total + 10000);
  assert.equal(totals2.total, 0);
  assert(totals2.total >= 0, 'total should never be negative');
});

test('applyVoucher does not mutate original invoice', () => {
  const result = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  });
  const invoice = result.value;
  const original = JSON.stringify(invoice);

  applyVoucher(invoice, { code: 'SUMMER10', amount: 5000 });
  assert.equal(JSON.stringify(invoice), original);
});

test('applyVoucher with complex invoice', () => {
  const result = createInvoice({
    customerId: 'C-003', // silver tier 2.5%
    issueDate: '2026-10-07',
    lines: [
      { sku: 'DES-HOUR', qty: 5 },
      { sku: 'DEV-HOUR', qty: 3, discountPercent: 10 },
      { sku: 'PRINT-A4', qty: 50 },
    ],
  });
  let invoice = result.value;
  const totals1 = invoiceTotals(invoice);

  // Apply voucher
  const voucherResult = applyVoucher(invoice, { code: 'PROMO15', amount: 15000 });
  assert.equal(voucherResult.ok, true);
  invoice = voucherResult.value;

  const totals2 = invoiceTotals(invoice);
  assert.equal(totals2.subtotal, totals1.subtotal);
  assert.equal(totals2.discount, totals1.discount);
  assert.equal(totals2.vat, totals1.vat);
  assert.equal(totals2.voucher, 15000);
  assert.equal(totals2.total, totals1.total - 15000);
});

test('createInvoice supports multiple lines', () => {
  const result = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-06',
    lines: [
      { sku: 'DEV-HOUR', qty: 10 },
      { sku: 'LOGO-PACK', qty: 1 },
    ],
  });
  assert.equal(result.ok, true);
  assert.equal(result.value.lines.length, 2);
  assert.equal(result.value.lines[0].name, 'Development (hour)');
  assert.equal(result.value.lines[1].name, 'Logo package');
});

test('createInvoice reports unknown customer', () => {
  const result = createInvoice({
    customerId: 'C-999',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
  });
  assert.deepEqual(result, { ok: false, error: 'CUSTOMER_NOT_FOUND' });
});

test('createInvoice rejects invalid date format', () => {
  assert.deepEqual(
    createInvoice({
      customerId: 'C-001',
      issueDate: '2026/10/07',
      lines: [{ sku: 'DES-HOUR', qty: 1 }],
    }),
    { ok: false, error: 'DATE_INVALID' }
