test('invoiceTotals with tier discounts', () => {
  // C-001 is gold (5%)
  // DES-HOUR: 5 * 8500 = 42500, 5% discount = 2125, after discount = 40375
  // VAT 21% on 40375 = 8478.75 = 8479
  // total = 42500 - 2125 + 8479 = 48854
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  });
  const totals = invoiceTotals(result.value);
