  assert.equal(totals.discount, 2125);
  assert.equal(totals.vat, 8479);
  assert.equal(totals.total, 48854);
});

test('invoiceTotals with multiple tier levels', () => {
  // Different discounts per line based on explicit value vs tier
  const invoice = {
    customerId: 'C-001',
    issueDate: '2026-10-07',
    status: 'draft',
    lines: [
      { qty: 5, unitPrice: 8500, discountPercent: 5, vatRate: 21 },      // 42500 - 2125 = 40375
      { qty: 3, unitPrice: 9500, discountPercent: 10, vatRate: 21 },     // 28500 - 2850 = 25650
    ],
  };
  const totals = invoiceTotals(invoice);
  // subtotal: 42500 + 28500 = 71000
  // discount: 2125 + 2850 = 4975
  // total before VAT: 71000 - 4975 = 66025
  // VAT: (40375 * 0.21) + (25650 * 0.21) = 8478.75 + 5386.50 = 13865.25 = 13865 (rounded)
  assert.equal(totals.subtotal, 71000);
  assert.equal(totals.discount, 4975);
  assert.equal(totals.vat, 13865);
  assert.equal(totals.total, 79890);
});

test('lineVAT calculates VAT on amount after discount', () => {
  // Line: 5 * 8500 = 42500, 10% discount = 4250, amount after = 38250
  // VAT 21% = 38250 * 0.21 = 8032.50 = 8032 (banker's rounding: half to even)
  const vat = lineVAT({ qty: 5, unitPrice: 8500, discountPercent: 10, vatRate: 21 });
  assert.equal(vat, 8032);
});

test('lineVAT with no discount', () => {
  // Line: 5 * 8500 = 42500, no discount, amount after = 42500
  // VAT 21% = 42500 * 0.21 = 8925
  const vat = lineVAT({ qty: 5, unitPrice: 8500, discountPercent: 0, vatRate: 21 });
  assert.equal(vat, 8925);
});

test('lineVAT with zero VAT rate', () => {
  // Line: 5 * 8500 = 42500, 10% discount = 4250, amount after = 38250
  // VAT 0% = 0
  const vat = lineVAT({ qty: 5, unitPrice: 8500, discountPercent: 10, vatRate: 0 });
  assert.equal(vat, 0);
});

test('lineVAT with 9% VAT rate', () => {
  // Line: 10 * 1000 = 10000, bulk discount 2.5% = 250, amount after = 9750
  // VAT 9% = 9750 * 0.09 = 877.5 ≈ 878
  const vat = lineVAT({ qty: 10, unitPrice: 1000, vatRate: 9 });
  assert.equal(vat, 878);
});

test('lineVAT with 21% VAT rate', () => {
  // Line: 10 * 1000 = 10000, bulk discount 2.5% = 250, amount after = 9750
  // VAT 21% = 9750 * 0.21 = 2047.5 ≈ 2048
  const vat = lineVAT({ qty: 10, unitPrice: 1000, vatRate: 21 });
  assert.equal(vat, 2048);
});

