});

test('invoiceTotals with discount and VAT', () => {
  const invoice = {
    customerId: 'C-002',
    issueDate: '2026-10-07',
    status: 'draft',
    lines: [{ qty: 10, unitPrice: 10000, discountPercent: 20, vatRate: 21 }],
  };
  const totals = invoiceTotals(invoice);
  // subtotal: 100000
  // discount: 20000
  // amount after discount: 80000
  // VAT 21% on 80000: 16800
  // total: 100000 - 20000 + 16800 = 96800
  assert.equal(totals.subtotal, 100000);
  assert.equal(totals.discount, 20000);
  assert.equal(totals.vat, 16800);
  assert.equal(totals.total, 96800);
});

test('invoiceTotals with complex scenario (multiple lines, tiers, discounts, VATs)', () => {
  const result = createInvoice({
    customerId: 'C-003',  // silver tier 2.5%
    issueDate: '2026-10-07',
    lines: [
      { sku: 'DES-HOUR', qty: 10 },           // 85000, discount 2.5% = 2125, VAT 21% on 82875 = 17404
      { sku: 'PRINT-A4', qty: 50, discountPercent: 10 }, // 1850, discount 10% = 185, VAT 9% on 1665 = 150
    ],
  });
  const totals = invoiceTotals(result.value);
  // subtotal: 85000 + 1850 = 86850
  // discount: 2125 + 185 = 2310
  // VAT: 17404 + 150 = 17554
  // total: 86850 - 2310 + 17554 = 102094
  assert.equal(totals.subtotal, 86850);
  assert.equal(totals.discount, 2310);
  assert.equal(totals.vat, 17554);
  assert.equal(totals.total, 102094);
});

